function productArt(p){return p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:`<div class="product-placeholder">${icon(p.category)}<span>Illustration</span></div>`}
function productCard(p){return `<article class="product-card"><a class="product-image" href="#product-${p.id}" aria-label="View ${p.name}">${productArt(p)}</a><div class="product-body"><h3><a href="#product-${p.id}">${p.name}</a></h3><p>${p.summary}</p><p class="unit-label">Order unit: <strong>${p.unit}</strong></p><span class="pricing-label">Request pricing</span><div class="product-controls"><label class="sr-only" for="qty-${p.id}">Quantity for ${p.name}</label><input id="qty-${p.id}" type="number" min="1" max="999999" step="1" value="1"><button class="btn dark" data-product="${p.id}">Add to quote</button></div></div></article>`}
function addProduct(id,quantity){const p=products.find(p=>p.id===id);if(!p)return;if(!Number.isInteger(quantity)||quantity<1||quantity>999999){toast('Enter a whole quantity between 1 and 999,999.');return}const existing=items.find(i=>i.productId===id);if(existing)existing.quantity=Math.min(999999,Number(existing.quantity)+quantity);else items.push({productId:p.id,description:`${p.name} — ${p.summary}`,quantity,unit:p.unit});updateCount();toast(`${quantity} × ${p.name} added to your quote basket.`)}
function bindProducts(){main.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>addProduct(b.dataset.product,Number(document.getElementById('qty-'+b.dataset.product).value)));}
function catalogue(){const params=new URLSearchParams(location.hash.split('?')[1]||'');return `<section class="catalogue-heading"><div class="wrap"><span class="eyebrow">Stationery catalogue</span><h1>Find products for your quote</h1><p>Choose products and quantities, then review your quote basket or attach your own list.</p></div></section><section class="catalogue-section"><div class="wrap catalogue-layout"><aside class="catalogue-filters"><h2>Categories</h2><label class="sr-only" for="category-filter">Filter by category</label><select id="category-filter"><option value="">All categories</option>${categories.map(c=>`<option value="${c[2]}" ${params.get('category')===c[2]?'selected':''}>${c[0]}</option>`).join('')}</select><div class="filter-links">${categories.map(c=>`<button type="button" data-filter="${c[2]}">${c[0]}</button>`).join('')}</div><div class="filter-help"><h3>Have your own list?</h3><p>Upload a document instead of selecting products.</p><a href="#upload">Upload your list</a></div></aside><div><div class="catalogue-tools"><div><label for="catalogue-search">Search products and specifications</label><input id="catalogue-search" type="search" value="${esc(params.get('q')||'')}" placeholder="Try A4, 80 gsm, pens or notebooks"></div><div><label for="catalogue-sort">Sort by</label><select id="catalogue-sort"><option value="default">Featured order</option><option value="name">Name A–Z</option></select></div></div><p class="sample-note">Sample range • Illustrations are temporary • Brands, prices and availability to be confirmed.</p><div class="catalogue-results-line"><span id="result-count" role="status"></span><button class="clear-filters" id="reset-filters">Clear filters</button><a href="#basket">View quote basket <span class="basket-count"></span></a></div><div class="product-grid" id="product-results"></div></div></div></section>`}
function bindCatalogue(){function refresh(){const q=$('#catalogue-search').value.trim().toLowerCase();const cat=$('#category-filter').value;let shown=products.filter(p=>(!cat||p.category===cat)&&[p.name,p.summary,p.unit,JSON.stringify(p.specs),categories.find(c=>c[2]===p.category)[0]].join(' ').toLowerCase().includes(q));if($('#catalogue-sort').value==='name')shown.sort((a,b)=>a.name.localeCompare(b.name));$('#result-count').textContent=`${shown.length} product${shown.length===1?'':'s'}`;$('#product-results').innerHTML=shown.map(productCard).join('')||'<div class="empty"><h3>No matching products</h3><p>Try a broader search, clear filters or describe your requirement in an uploaded list.</p><a href="#upload">Upload your list</a></div>';bindProducts();}$('#catalogue-search').oninput=refresh;$('#category-filter').onchange=refresh;$('#catalogue-sort').onchange=refresh;$('#reset-filters').onclick=()=>{$('#catalogue-search').value='';$('#category-filter').value='';$('#catalogue-sort').value='default';refresh()};main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{$('#category-filter').value=b.dataset.filter;refresh()});refresh()}
function productPage(id){const p=products.find(p=>p.id===id);if(!p)return pageHero('Catalogue','Product not found','Browse the catalogue to select a product.')+'<div class="wrap section"><a href="#stationery">Back to products</a></div>';return `<section class="section product-detail"><div class="wrap"><a class="breadcrumb" href="#stationery?category=${p.category}">← ${categories.find(c=>c[2]===p.category)[0]}</a><div class="product-detail-grid"><div class="detail-image">${productArt(p)}</div><div><span class="eyebrow">Sample product</span><h1>${p.name}</h1><p>${p.summary}</p><p class="pricing-label">Request pricing</p><dl class="product-specifications">${Object.entries(p.specs).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>Order unit</dt><dd>${p.unit}</dd></div><div><dt>Brand</dt><dd>${p.brand}</dd></div></dl><label for="qty-${p.id}" class="qty-detail-label">Quantity (${p.unit.toLowerCase()})</label><div class="product-controls detail-controls"><input id="qty-${p.id}" type="number" min="1" max="999999" step="1" value="1"><button class="btn dark" data-product="${p.id}">Add to quote basket</button></div><p class="help">Sample specification. Final product details and availability to be confirmed.</p><a class="text-link" href="#basket">Review your quote basket</a></div></div></div></section>`}
function basket(){return `<section class="catalogue-heading"><div class="wrap"><span class="eyebrow">Quotation request</span><h1>Your quote basket</h1><p>Review specifications, quantities and order units before entering your contact and delivery details.</p></div></section><section class="section basket-section"><div class="wrap basket-layout"><div>${items.length?`<div class="basket-items">${items.map((x,i)=>{const p=products.find(p=>p.id===x.productId);return `<article class="basket-item">${p?`<div class="basket-thumb">${productArt(p)}</div>`:''}<div class="basket-description"><h2>${esc(x.description)}</h2><p>Order unit: ${esc(x.unit||'Specify pack size in the request')}</p><span>Pricing to be confirmed</span></div><div><label for="basket-qty-${i}">Quantity</label><input id="basket-qty-${i}" type="number" min="1" max="999999" step="1" value="${esc(x.quantity)}" data-basket-qty="${i}"><button class="remove-item" data-basket-remove="${i}">Remove</button></div></article>`}).join('')}</div><a class="text-link" href="#stationery">Continue browsing</a>`:`<div class="empty"><h2>Your quote basket is empty</h2><p>Add products from the catalogue or upload your own stationery list.</p><a class="btn dark" href="#stationery">Browse products</a><a class="btn outline" href="#upload">Upload your list</a></div>`}</div><aside class="basket-summary"><h2>Request summary</h2><dl><div><dt>Item lines</dt><dd>${items.length}</dd></div><div><dt>Prices and availability</dt><dd>To be quoted</dd></div><div><dt>Delivery charges</dt><dd>Subject to location</dd></div></dl><p>Amounts and applicable VAT will be included in the quotation. Mixed packs and units are kept separate.</p>${items.length?'<button class="btn dark" id="basket-continue">Continue to enquiry</button>':''}<a class="btn outline" href="#upload">Upload your list</a><p class="help">Prototype: the enquiry can be downloaded for review. Nothing is sent to Lepetse.</p></aside></div></section>`}
function bindBasket(){main.querySelectorAll('[data-basket-qty]').forEach(e=>{e.oninput=()=>{const q=Number(e.value);if(Number.isInteger(q)&&q>=1&&q<=999999)items[Number(e.dataset.basketQty)].quantity=q};e.onchange=()=>{if(!e.checkValidity()){e.value=items[Number(e.dataset.basketQty)].quantity;toast('Enter a whole quantity between 1 and 999,999.')}}});main.querySelectorAll('[data-basket-remove]').forEach(e=>e.onclick=()=>{items.splice(Number(e.dataset.basketRemove),1);main.innerHTML=basket();bindBasket();updateCount()});$('#basket-continue')?.addEventListener('click',()=>{const bad=[...main.querySelectorAll('[data-basket-qty]')].find(e=>!e.value||!e.checkValidity());if(bad){bad.reportValidity();return}capture();step=0;location.hash='quote'})}
